export const WORDS=['太阳','月亮','雨伞','苹果','飞机','汽车','小猫','大树','房子','花朵','蛋糕','小鱼'];
export function sketchStart(){return{game:'draw',cells:[0,0],turn:1,winner:0,over:false,moves:0,fen:WORDS[Math.floor(Math.random()*WORDS.length)],history:[]};}
export function sketchNext(s,correct=false){const cells=s.cells.slice();if(correct){cells[s.turn-1]++;cells[2-s.turn]+=2;}const moves=s.moves+1;return moves===6?{...s,cells,moves,over:true,winner:cells[0]===cells[1]?0:cells[0]>cells[1]?1:2}:{...sketchStart(),cells,moves,turn:3-s.turn};}
export function drawSketch(host,s,{you,network,send,practice,next}){
 if(!host.querySelector('canvas')){host.innerHTML='<p class="sketch-prompt"></p><canvas width="800" height="600" aria-label="绘画区"></canvas><div class="sketch-controls"><button type="button" data-clear>清空画布</button><button type="button" data-pass>交给好友猜</button><button type="button" data-next>下一题</button></div><form class="sketch-guess"><input aria-label="你的答案" maxlength="40" placeholder="输入你的答案" required><button>猜一猜</button></form><p class="sketch-feedback" role="status"></p>';
 const canvas=host.querySelector('canvas');let points=null;const point=e=>{const r=canvas.getBoundingClientRect();return[Math.max(0,Math.min(1000,Math.round((e.clientX-r.left)/r.width*1000))),Math.max(0,Math.min(1000,Math.round((e.clientY-r.top)/r.height*1000)))];};
 canvas.onpointerdown=e=>{if(!host._drawAllowed)return;canvas.setPointerCapture(e.pointerId);points=point(e);};canvas.onpointermove=e=>{if(!points||points.length>=598)return;points.push(...point(e));paint(host._state.history,points);};canvas.onpointerup=async()=>{if(!points)return;const stroke=points;points=null;if(stroke.length>=4)await host._send('stroke',null,stroke);};canvas.onpointercancel=()=>{points=null;paint(host._state.history);};host.querySelector('[data-clear]').onclick=()=>host._send('clear');host.querySelector('[data-pass]').onclick=()=>{host._passed=true;host._rerender();};host.querySelector('[data-next]').onclick=()=>host._next();host.querySelector('form').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input'),oldMoves=host._state.moves;await host._send('guess',input.value);host.querySelector('.sketch-feedback').textContent=host._state.moves!==oldMoves?'答对了！进入下一题。':'还没有猜对，再想想。';input.value='';};
 }
 host._state=s;host._send=send;host._next=next;host._rerender=()=>drawSketch(host,host._state,{you,network,send,practice,next});
 const drawer=!practice&&!host._passed&&you===s.turn&&!s.over;host._drawAllowed=drawer;host.querySelector('.sketch-prompt').textContent=s.over?'绘画结束 · '+s.cells.join(' : '):'第 '+(s.moves+1)+' / 6 题 · '+(drawer?'请画：'+s.fen:'猜猜画的是什么 · '+s.fen.length+' 个字');host.querySelector('[data-clear]').hidden=!drawer;host.querySelector('[data-pass]').hidden=network||practice||!drawer;host.querySelector('[data-next]').hidden=network||s.over;host.querySelector('form').hidden=drawer||s.over;paint(s.history);
 function paint(history,extra){const c=host.querySelector('canvas'),ctx=c.getContext('2d');ctx.clearRect(0,0,800,600);ctx.lineWidth=5;ctx.strokeStyle='#20344f';ctx.lineCap='round';ctx.lineJoin='round';for(const line of [...history,...(extra?[extra.join(',')]:[])]){const p=line.split(',').map(Number);ctx.beginPath();for(let i=0;i<p.length;i+=2){const x=p[i]*.8,y=p[i+1]*.6;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}}
}
